var supplier = new RecordingSupplier(true);
var controller = new StockController(supplier);
var item = new StockItem { Sku = "SKU-1", OnHand = 10, Reserved = 0, ReorderPoint = 15 };

var firstPlaced = controller.PlaceReorder(item);
Check.True(firstPlaced);
Check.Equal(1, supplier.CallCount);
Check.Equal("SKU-1", supplier.LastSku);
Check.Equal(20, supplier.LastQuantity);

var secondPlaced = controller.PlaceReorder(item);
Check.False(secondPlaced);
Check.Equal(1, supplier.CallCount);

var partialDeliveryConfirmed = controller.ConfirmDelivery(item, 5);
Check.True(partialDeliveryConfirmed);
Check.Equal(15, item.OnHand);

var thirdPlaced = controller.PlaceReorder(item);
Check.True(thirdPlaced);
Check.Equal(2, supplier.CallCount);
Check.Equal("SKU-1", supplier.LastSku);
Check.Equal(15, supplier.LastQuantity);

public sealed class RecordingSupplier : ISupplier
{
    private readonly bool _result;

    public RecordingSupplier(bool result)
    {
        _result = result;
    }

    public int CallCount { get; private set; }
    public string? LastSku { get; private set; }
    public int LastQuantity { get; private set; }

    public bool PlaceOrder(string sku, int quantity)
    {
        CallCount++;
        LastSku = sku;
        LastQuantity = quantity;
        return _result;
    }
}
